import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/2026%E5%B9%B411%E6%9C%88%E4%B8%8A%E6%97%AC%E3%81%AE%E9%9B%91%E8%A8%98.html","title":"2026年11月上旬の雑記","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.14,"words":343},"filePathRelative":"2026年11月上旬の雑記.md"}`),a={name:`2026年11月上旬の雑記.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="_2026年11月上旬の雑記" tabindex="-1"><a class="header-anchor" href="#_2026年11月上旬の雑記"><span>2026年11月上旬の雑記</span></a></h1><h2 id="_2026-11-01-日" tabindex="-1"><a class="header-anchor" href="#_2026-11-01-日"><span>2026-11-01 (日)</span></a></h2><p>台風ウィークになり、ちょっとサーフィンの疲労が溜まってきている。 今日は昼からサーフィンの予定。午前中は<a href="./強化学習.html">強化学習</a>の動画を見たりする。</p><p>昼前からサーフィン＞<a href="./SurfLog.html">SurfLog</a></p><p>夕方兄の2ラウンド目のサーフィンを見学に。良く頑張るな。</p><p>夜は<a href="./強化学習.html">強化学習</a>の<a href="./ModelFreePolicyImprovement.html">ModelFreePolicyImprovement</a>のノートづくり。だいぶいい感じになってきた。</p><h2 id="_2026-11-03-火" tabindex="-1"><a class="header-anchor" href="#_2026-11-03-火"><span>2026-11-03 (火)</span></a></h2><p>今日は波がだいぶ落ちて祝日との事で混んでそうなので昼くらいを狙う。</p><p>ポッドキャストをとったり、<a href="./TeFWiki.html">TeFWiki</a>のElectron版のeditボタンをバックリンクより上に変えたり。 TeFWikiを自分で作ったのはいい判断だったな。 やはりこういう自分の中核になるアプリはシンプルに保って自分の思うようにしておく、というのは正しい気がする。</p><p>何は自分で作って何は人の作ったものを使うか、というのは、昔と今ではまたずいぶんと判断基準が変わったトピックだよな。</p><p><a href="./強化学習.html">強化学習</a>の動画を眺める。最初はなんの話か良くわかってなかったが、話が進むとちょっっとずつ分かってきた。 なんかLecture 5は話の進め方が洗練されてない気はするな。</p><p>podcastをとったりブログを書いたりして過ごす。 ノートPCよりも<a href="./Supernote.html">Supernote</a>+<a href="./Rhinocs.html">Rhinocs</a>の方がブログ書くのに集中出来るな。 e-inkである必要性はあまり無く、Androidタブレットでも十分な気はするが。</p><p>どうも波は落ちてしまった模様。まぁ混んでそうだったし、今日はいいか。</p><p>ドトールにでも行くか、と家を出たが混んでてカフェ難民に。 祝日とかで定休日のはずの図書館があいてたので少し本を読んだり散歩したり。</p><p>帰りにモスを見たらすいてたのでモスで軽く読書。 語学をやりたい気分だが<a href="./ニューエクスプレスインドネシア語.html">ニューエクスプレスインドネシア語</a>はちょっと重いので、 もうすこし軽く読める<a href="./インドネシア語のしくみ.html">インドネシア語のしくみ</a>を読む。</p><h2 id="_2026-11-08-日" tabindex="-1"><a class="header-anchor" href="#_2026-11-08-日"><span>2026-11-08 (日)</span></a></h2><p>ここ数日はずっとサーフィンばかりしていたが、今日は久しぶりに波が無いという事で日常生活の立て直し。</p><p>最近はサーフィンした後は疲れてしまってずっと布団の上で生活している感じだったが、その上での生活はまぁまぁだった。 インドネシア語は結構進んでいて、入門の壁は越えつつある気がする。</p><p>午後は<a href="./強化学習.html">強化学習</a>の続きを進める。だいぶ日常生活に復帰出来てきたな。</p><h2 id="_2026-11-09-月" tabindex="-1"><a class="header-anchor" href="#_2026-11-09-月"><span>2026-11-09 (月)</span></a></h2><p>今日はインフルエンザの予防接種だったが雨降ってる。ぐぬぬ。</p><p>午前中は<a href="./強化学習.html">強化学習</a>。</p><p>午後はインドネシア語を進めたり。<a href="./インドネシア語のしくみ.html">インドネシア語のしくみ</a>を最後まで読み終わる。</p><p><a href="./Rhinocs.html">Rhinocs</a>のインテントに対応するなど。persistableじゃないので区別するのが面倒だなぁ、と思っていたが、Supernoteで<a href="./TeFWiki.html">TeFWiki</a>から開きたいことがあるので、諦めて実装。 前回途中までやってたstashがあったのでそこから戻してちょこちょこ修正して完成。</p><p>夜はルソーの社会契約論を読んだり、<a href="./大衆の反逆.html">大衆の反逆</a>を聴いたり。</p><h2 id="_2026-11-10-火" tabindex="-1"><a class="header-anchor" href="#_2026-11-10-火"><span>2026-11-10 (火)</span></a></h2><p>今日も雨で寒い。こういう日は海行く気なくすな。波も無さそうだが。</p><p>午前中は<a href="./大衆の反逆.html">大衆の反逆</a>の感想を書いたりしていた。</p><p>午後は<a href="./強化学習.html">強化学習</a>を進めたり。Lecture 5はあと少し。</p>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};